WITH latest AS (SELECT * FROM store_sales QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY sale_date DESC NULLS FIRST, id) = 1), deduped AS (SELECT id, product_id, revenue FROM latest QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY sale_date, id) = 1), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue DESC NULLS FIRST, id) AS rank_in_group FROM deduped QUALIFY rank_in_group = 1), joined AS (SELECT e.id, e.product_id, e.rank_in_group, p.category, p.launch_date FROM ranked e INNER JOIN products p ON e.product_id = p.id WHERE p.stock_qty >= 109) SELECT id, category FROM joined ORDER BY category DESC
